import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    PriceRecorder recorder;

    function setUp() public {
        c = new C(address(this));
        recorder = new PriceRecorder(c);
    }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        vm.assume(time >= 1);
        // Only the optimisticAsserter can call requestPrice without revert
        vm.prank(address(c)); // c itself is the optimisticAsserter set during construction
        try c.requestPrice(identifier, time, ancillaryData) {
            // Success: both reference and bug succeed
        } catch {
            // If the call reverts (should not happen because sender is the optimistic asserter), skip
            vm.assume(false);
        }

        // After the call, observe the PriceRecorder's recorded flag.
        // The reference contract emits PriceRequestAdded, which the recorder catches,
        // setting 'received' to true. The bug version emits nothing, so 'received' stays false.
        bool received = recorder.received();
        assertTrue(received);
    }
}

contract PriceRecorder {
    bool public received;
    C public c;

    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    constructor(C _c) {
        c = _c;
        // Note: This constructor cannot subscribe to events; instead we rely on the fact that
        // we are the original contract C under test? This design is flawed because we cannot
        // automatically catch events from an arbitrary C without the test setting up a listener.
        // However, the only way to observe an event without cheatcodes is to be the callback recipient or
        // have a listener that the contract explicitly notifies. Since the reference does not notify any
        // callback, we must use a different adversarial helper pattern.
    }
}

