import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully) public {
        // Any caller other than the optimistic asserter MUST NOT be able to call assertionResolvedCallback.
        // The correct C has onlyOptimisticAsserter on assertionResolvedCallback, so a direct call from a non-asserter reverts.
        // The bug removes that modifier, so a direct call from anyone succeeds without revert.
        vm.assume(msg.sender != address(c.optimisticAsserter()));

        bool rejected = false;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            rejected = false;
        } catch {
            rejected = true;
        }

        // The correct version always reverts for a non-asserter caller, the buggy one succeeds for some input.
        assertTrue(rejected);
    }
}

